// Normalize a Meta lead into the shape /api/ingest expects.
// Replace the field mapping with your real Lead Ads form field names, or
// (better) use the Facebook Lead Ads trigger node to fetch full field_data.

const ACCOUNT_ID = '<<PUT-YOUR-ACCOUNT-ID>>'; // from Settings page in the app

function normPhone(raw) {
  if (!raw) return null;
  let p = String(raw).replace(/[^0-9+]/g, '');
  if (p.startsWith('00')) p = '+' + p.slice(2);
  if (!p.startsWith('+')) {
    // Egypt local (01xxxxxxxxx) -> +20
    if (p.startsWith('0')) p = '+20' + p.slice(1);
    else p = '+' + p;
  }
  return p;
}

const body = $json.body || $json;
const fields = body.field_data || {};

return [{
  json: {
    account_id: ACCOUNT_ID,
    meta_lead_id: body.leadgen_id || body.lead_id || null,
    full_name: fields.full_name || body.full_name || null,
    phone: normPhone(fields.phone_number || body.phone || null),
    email: fields.email || body.email || null,
    fbclid: body.fbclid || null,
    campaign_id: body.campaign_id || null,
    adset_id: body.adset_id || null,
    ad_meta_id: body.ad_id || null
  }
}];
